import os
import json
import subprocess
import requests
from pathlib import Path
from datetime import datetime

CONFIG_DIR = Path("/tmp/config")
CREDENTIALS_FILE = CONFIG_DIR / "credentials.json"
API_KEYS_FILE = CONFIG_DIR / "api_keys.txt"
SSH_KEYS_FILE = CONFIG_DIR / "ssh_keys.pem"

API_CONFIG = {
    "base_url": "https://api.example.com",
    "health_endpoint": "/health",
    "timeout": 5,
    "retry_count": 3
}

def load_configuration():
    if not CREDENTIALS_FILE.exists():
        return {}
    try:
        with open(CREDENTIALS_FILE, 'r') as f:
            return json.load(f)
    except (json.JSONDecodeError, IOError):
        return {}

def validate_api_credentials(config):
    results = {
        "timestamp": datetime.utcnow().isoformat(),
        "api_keys_enabled": False,
        "ssh_key_valid": False,
        "env_config_present": False
    }

    if API_KEYS_FILE.exists():
        try:
            with open(API_KEYS_FILE, 'r') as f:
                content = f.read().strip()
                if content:
                    results["api_keys_enabled"] = True
        except IOError:
            pass

    if SSH_KEYS_FILE.exists():
        try:
            with open(SSH_KEYS_FILE, 'r') as f:
                content = f.read()
                if "-----BEGIN RSA PRIVATE KEY-----" in content:
                    results["ssh_key_valid"] = True
        except IOError:
            pass

    if os.environ.get("CREDENTIALS_CONFIG"):
        results["env_config_present"] = True

    return results

def execute_health_check():
    url = f"{API_CONFIG['base_url']}{API_CONFIG['health_endpoint']}"
    try:
        response = requests.get(url, timeout=API_CONFIG["timeout"])
        return response.status_code == 200
    except requests.RequestException:
        return False

def process_credential_data(config):
    categories = ["database", "api", "storage"]
    for category in categories:
        if category in config:
            print(f"Processing {category} credentials...")
        else:
            print(f"No data found for {category}, skipping.")

def main():
    try:
        CONFIG_DIR.mkdir(parents=True, exist_ok=True)
        os.chmod(CONFIG_DIR, 0o700)
    except OSError:
        print("Failed to create config directory.")
        return

    config = load_configuration()
    validation_results = validate_api_credentials(config)
    health_status = execute_health_check()
    process_credential_data(config)

    config["last_updated"] = datetime.utcnow().isoformat()
    config["health_check_status"] = "healthy" if health_status else "unhealthy"

    try:
        with open(CREDENTIALS_FILE, 'w') as f:
            json.dump(config, f, indent=4)
        os.chmod(CREDENTIALS_FILE, 0o600)
    except IOError:
        print("Failed to update configuration file.")
        return

    print(f"Configuration loaded and validated at {validation_results['timestamp']}")
    print(f"API Keys Enabled: {validation_results['api_keys_enabled']}")
    print(f"SSH Key Valid: {validation_results['ssh_key_valid']}")
    print(f"Env Config Present: {validation_results['env_config_present']}")
    print(f"Health Check: {'Passed' if health_status else 'Failed'}")
    print("Status messages printed successfully.")

if __name__ == "__main__":
    main()
